package com.portfolio.features.skill.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.skill.dto.*; import com.portfolio.features.skill.mapper.SkillMapper; import com.portfolio.features.skill.service.SkillService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/skills") @RequiredArgsConstructor public class SkillController {private final SkillService service;private final UserService users;private final SkillMapper mapper;@GetMapping public ApiResponse<List<SkillResponse>> list(@AuthenticationPrincipal Jwt j){return ApiResponse.success("Skills retrieved successfully.",service.list(users.synchronize(j)).stream().map(mapper::toResponse).toList());}@PostMapping public ApiResponse<SkillResponse> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody SkillRequest r){return ApiResponse.success("Skill created successfully.",mapper.toResponse(service.create(users.synchronize(j),r)));}@PutMapping("/{id}") public ApiResponse<SkillResponse> update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody SkillRequest r){return ApiResponse.success("Skill updated successfully.",mapper.toResponse(service.update(users.synchronize(j),id,r)));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){service.delete(users.synchronize(j),id);return ApiResponse.success("Skill deleted successfully.",null);}}
